---@class QTE3Mgr
local QTE3Mgr = Class('QTE3Mgr')

function QTE3Mgr:__init()
    --
end

function QTE3Mgr:__delete()
    --
    self.uiStack = nil
    self.cacheStack = nil
    self.cacheCam = nil
end

function QTE3Mgr:Awake()
end

function QTE3Mgr:Start()
end

function QTE3Mgr:Initialize()
    self.processor = self.controller.gameObject:GetComponentInChildren(typeof(ChapterProcessor))
    self.markers = self.processor:GetAllWaitTLFinishMarkers()
    local CameraType = CS.UnityEngine.Camera
    self.cacheCam = camCtrl.mainCamera.gameObject:GetComponent(typeof(CS.UnityEngine.Rendering.Universal.UniversalAdditionalCameraData))
    local uiCam = self.controller.transform:Find("UICameraTop"):GetComponent(typeof(CameraType))
    -- self.cacheCam.cameraStack:Clear()
    -- self.cacheCam.cameraStack:Add(uiCam)
    camCtrl:ClearCameraStack(camCtrl.mainCamera)
    camCtrl:AddCamera(uiCam)

    self.brain = camCtrl.mainCamera.gameObject:GetComponent(typeof(CinemachineBrain))
    self.define = self.brain.m_DefaultBlend
    local define = CinemachineBlendDefinition()
    define.m_Time = 0
    self.brain.m_DefaultBlend = define
    
end

function QTE3Mgr:StartPlay()
    self.waitCo = cs_coroutine.start(function()

        printInfo("qte3 start")
        local director = nil
        local pre = nil
        if isNull(self.markers) then
            return
        end

        for i = 1, self.markers.Count do
            director = self.markers[i - 1].Director:Resolve(self.processor.DirectorControl)
            if not isNull(director) then
                KTool.SetActive(director.gameObject, true)

                if director.gameObject.name == "OP3_part02"  then
                    CriWareUtils.StopAll(true)
                    KTool.SetActive(camCtrl.mainCamera, false)
                elseif director.gameObject.name == "OP3_part01_4" then
                    KTool.SetActive(camCtrl.mainCamera, false)
                end

                --self:BindModel(director, self.model)
                if not isNull(BattleViewMgr) then
                    BattleViewMgr:BindRoleInEnterTimeline(director)
                end

                if not isNull(pre) then
                    KTool.SetActive(pre, false)
                end

                pre = director
                director:Play()

                if not isNull(self.processor.OnSingleChapterStart) then
                    self.processor.OnSingleChapterStart(director)
                end

                coroutine.yield(WaitForTimelineFinish(director))

                if not isNull(self.processor.OnSingleChapterFinish) then
                    self.processor.OnSingleChapterFinish(director)
                end

                --if director.gameObject.name == "" then
                --    KTool.SetActive(self.model, false)
                --end
                if director.gameObject.name == "OP3_part02"  then
                    CriWareUtils.PlayLastBGMMusic()
                    KTool.SetActive(camCtrl.mainCamera, true)
                elseif director.gameObject.name == "OP3_part01_4" then
                    KTool.SetActive(camCtrl.mainCamera, true)
                end
            end
        end

        
        local tb = {}
        tb[1] = {
            position = Vector3(5.777185, 0, 11.86769),
            rotation = Vector3(0, -158.67, 0),
        }
        
        tb[1000] = {
            position = Vector3(2.722337, 0, 2.152393),
            rotation = Vector3(0, 20, 0),
        }
        
        BattleViewMgr:OnEnterTimelineFinished(tb)


        -- self.cacheCam.cameraStack:Clear()
        camCtrl:ClearCameraStack(camCtrl.mainCamera)
        camCtrl:InitCameraStack(camCtrl.mainCamera)
        
        if not isNull(self.processor.OnChapterFinish) then
            self.processor.OnChapterFinish()
        end
        
        self.brain.m_DefaultBlend = self.define


        printInfo("qte3 end")
    end)
    
    return self.waitCo
end

function QTE3Mgr:OnDestroy()
    if self.waitCo then
        cs_coroutine.stop(self.waitCo)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return QTE3Mgr